import{$ as e,Z as t,pt as n,s as r}from"./chunks/framework.BTiPPQh6.js";import"./chunks/assets.qdzaMdnh.js";var i=JSON.parse(`{"title":"Cloudflare supports Vite's mission","description":"","frontmatter":{"title":"Cloudflare supports Vite's mission","author":{"name":"The Vite Team"},"date":"2026-06-04T00:00:00.000Z","sidebar":false,"head":[["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Cloudflare supports Vite's mission"}],["meta",{"property":"og:image","content":"https://vite.dev/og-image-cloudflare-supports-vite.webp"}],["meta",{"property":"og:url","content":"https://vite.dev/blog/cloudflare-supports-vite"}],["meta",{"property":"og:description","content":"The VoidZero team is joining Cloudflare. Vite remains MIT, vendor-neutral and stewarded by the same wider team."}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"blog/cloudflare-supports-vite.md","filePath":"blog/cloudflare-supports-vite.md"}`),a={name:`blog/cloudflare-supports-vite.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="cloudflare-supports-vite-s-mission" tabindex="-1">Cloudflare supports Vite&#39;s mission <a class="header-anchor" href="#cloudflare-supports-vite-s-mission" aria-label="Permalink to “Cloudflare supports Vite&#39;s mission”">​</a></h1><p><em>June 4, 2026</em></p><p><img src="/og-image-cloudflare-supports-vite.webp" alt="Cloudflare Supports Vite&#39;s Mission Cover Image" width="1530" height="769"></p><p>Today marks the start of a new stage for Vite. VoidZero is joining Cloudflare. You can read the full story from Evan You in <a href="https://voidzero.dev/posts/voidzero-cloudflare" target="_blank" rel="noreferrer">VoidZero&#39;s announcement</a>. In <a href="https://blog.cloudflare.com/voidzero-joins-cloudflare/" target="_blank" rel="noreferrer">Cloudflare&#39;s blog post</a>, they explain why they are investing in the Vite stack, which has now become part of the web&#39;s foundational infrastructure. Vite&#39;s team governance, mission, and philosophy aren&#39;t changing:</p><ul><li>Vite remains open source under the MIT license.</li><li>Vite remains vendor-agnostic, applications built with vite are meant to run anywhere.</li><li>Vite continues to be stewarded by the <a href="/team">Vite team</a>, which includes members employed by different organizations and independent members.</li><li><a href="https://opencollective.com/vite" target="_blank" rel="noreferrer">Vite&#39;s Open Collective</a> funds are managed by the Vite team and are used to fund independent core team members, dependencies, and other key projects in the ecosystem.</li><li>The Vite team members employed by VoidZero are all joining Cloudflare and will continue to work on Vite.</li></ul><p>As stated in the VoidZero and Cloudflare announcements, the same applies to <a href="https://vitest.dev/team.html" target="_blank" rel="noreferrer">Vitest</a>, <a href="https://rolldown.rs/team" target="_blank" rel="noreferrer">Rolldown</a>, <a href="https://oxc.rs/team.html" target="_blank" rel="noreferrer">Oxc</a>, and <a href="https://viteplus.dev/team" target="_blank" rel="noreferrer">Vite+</a>.</p><h2 id="cloudflare-s-vite-ecosystem-open-source-fund" tabindex="-1">Cloudflare&#39;s Vite Ecosystem Open Source Fund <a class="header-anchor" href="#cloudflare-s-vite-ecosystem-open-source-fund" aria-label="Permalink to “Cloudflare&#39;s Vite Ecosystem Open Source Fund”">​</a></h2><p>Cloudflare is committed to helping Vite remain neutral and has also announced a new $1M open source fund for the Vite ecosystem. Alongside Vite&#39;s Open Collective (which stays managed by the Vite team), these funds will allow us to further improve Vite and its ecosystem, including:</p><ul><li>Fund more popular plugins and toolings in the ecosystem.</li><li>Adopt a core team member stipend to support independent team members.</li><li>Work closely with teams of the Vite stack, including Rolldown, Oxc, and Vite+.</li><li>Work closely with the ecosystem maintainers from frameworks, plugins, and deployment platforms.</li><li>Work with standard bodies and adopt new web platform features faster.</li><li>Audit and release security issues more quickly.</li></ul><p>Many of which we had already started working on, which will help accelerate the process.</p><h2 id="thank-you" tabindex="-1">Thank You <a class="header-anchor" href="#thank-you" aria-label="Permalink to “Thank You”">​</a></h2><p>We want to thank our current sponsors through <a href="https://github.com/sponsors/vitejs" target="_blank" rel="noreferrer">GitHub Sponsors</a> and <a href="https://opencollective.com/vite" target="_blank" rel="noreferrer">Open Collective</a>, which remain invaluable to us. We&#39;d also like to thank the teams from projects, ecosystem frameworks, and plugins whose collaboration helped Vite reach where it is today. And also to <a href="https://github.com/vitejs/vite/graphs/contributors" target="_blank" rel="noreferrer">the 1250+ contributors</a> to the Vite repo and the users who keep providing valuable feedback to improve Vite.</p><p>We talked about what&#39;s next in <a href="/blog/announcing-vite8#looking-ahead">Vite 8&#39;s announcement</a>. We have made good progress towards Full Bundle Mode and the new Ecosystem Sync Calls, that gathers members of different frameworks, deploy platforms, and plugins, have become a great motor for new ideas to further expand Vite&#39;s capabilities. We think we&#39;re on a good trajectory to stabilize Vite&#39;s Environment API on Vite 9. As Vite&#39;s story continues to unfold, we look forward to the long path ahead to keep building the web together.</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};